package in.anumati.platform.compliance; import java.time.*; import java.util.*; public record ComplianceResponse(UUID id,UUID businessProfileId,UUID applicationId,UUID approvalId,String name,String authority,String description,LocalDate dueDate,int reminderDays,ComplianceFrequency frequency,ComplianceStatus status,UUID sourceId,Instant completedAt,Instant updatedAt){static ComplianceResponse from(ComplianceObligation c){return new ComplianceResponse(c.getId(),c.getBusinessProfile().getId(),c.getApplication()==null?null:c.getApplication().getId(),c.getApproval()==null?null:c.getApproval().getId(),c.getName(),c.getAuthority(),c.getDescription(),c.getDueDate(),c.getReminderDays(),c.getFrequency(),c.getStatus(),c.getSource()==null?null:c.getSource().getId(),c.getCompletedAt(),c.getUpdatedAt());}}
